package local.pocketchat;

import android.app.Activity;
import android.content.Context;
import android.os.Bundle;
import android.widget.TextView;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Real encrypted catalog regression in the isolated .test app; never downloads a source or opens ChatGPT. */
public final class ExitSubscriptionCatalogTestActivity extends Activity {
  final JSONArray checks=new JSONArray();
  void check(String name,boolean condition){checks.put(J.obj("name",name,"pass",condition));if(!condition)throw new AssertionError(name);}
  byte[] provider(String password){return ("proxies:\n- {name: duplicate name, type: socks5, server: exit-a.example.invalid, port: 1080, username: fixture, password: '"+password+"'}\n- {name: duplicate name, type: socks5, server: exit-b.example.invalid, port: 1081}\n").getBytes(StandardCharsets.UTF_8);}
  @Override public void onCreate(Bundle state){super.onCreate(state);if(!getPackageName().endsWith(".test"))throw new SecurityException("isolated test application required");TextView text=new TextView(this);text.setText("Running encrypted exit subscription checks…");setContentView(text);new Thread(()->{String failure="";try{runChecks();}catch(Throwable error){failure=error.getClass().getSimpleName();checks.put(J.obj("name","catalog suite completed","pass",false));}String result=failure;try{int passed=0;for(int i=0;i<checks.length();i++)if(checks.optJSONObject(i).optBoolean("pass"))passed++;J.write(new java.io.File(getFilesDir(),"exit-subscription-catalog-results.json"),J.obj("passed",passed,"total",checks.length(),"checks",checks,"failureType",result,"scope","Android encrypted catalog and revision checks; no network, real account, or end-to-end browser validation").toString(2));}catch(Exception ignored){}runOnUiThread(()->text.setText(result.isEmpty()?"Exit subscription catalog checks passed":"Exit subscription catalog checks failed: "+result));},"exit-catalog-test").start();}
  void runChecks()throws Exception{
    Context fixture=Profiles.context(this,7);SecretStore vault=new SecretStore(fixture);String[] slots={"network","subscription","subscription-meta","subscription-ui","pending-network"};Map<String,byte[]> before=new HashMap<>();for(String slot:slots)before.put(slot,vault.get(slot));NetworkCatalog catalog=new NetworkCatalog(this);String sourceId="",generation="";
    try{
      ProfileCatalog.get(this).created(7);String url="https://exit-source.example.invalid/"+UUID.randomUUID();JSONObject entry=catalog.addSubscription("fixture entry",url);byte[] entryBytes="proxies:\n- {name: entry, type: socks5, server: entry.example.invalid, port: 1080}\n".getBytes(StandardCharsets.UTF_8);catalog.parsed(entry.optString("id"),J.arr("Entry|entry"),entryBytes,System.currentTimeMillis());
      JSONObject source=catalog.addExitSource("fixture exits",url);sourceId=source.optString("id");generation=source.optString("generation");check("entry and exit source namespaces are separate",!sourceId.equals(entry.optString("id"))&&!sourceId.equals(entry.optString("sourceId")));
      byte[] first=provider("old-fixture");catalog.parsedExitSource(sourceId,generation,0,ExitSubscriptionParser.parse(first),first,System.currentTimeMillis());source=catalog.exitSource(sourceId);String nodeId=source.optJSONArray("nodes").optString(0);JSONObject node=catalog.exit(nodeId);check("two duplicate labels retain distinct node identities",source.optJSONArray("nodes").length()==2&&!nodeId.equals(source.optJSONArray("nodes").optString(1)));
      check("encrypted exit cache round trips",Arrays.equals(first,catalog.exitCache(source)));check("raw encrypted file excludes source and credentials",!new String(new android.util.AtomicFile(catalog.store.file("network-catalog")).readFully(),StandardCharsets.UTF_8).contains("old-fixture"));
      JSONObject initial=J.obj("subscriptionUrl",url,"exitHost","manual.example.invalid","exitPort",1080,"entryMode","manual","entry","Entry|entry","entryPool",J.arr("Entry|entry"));vault.save(initial);catalog.addExit("fixture manual","","manual.example.invalid",1080,"","");NetworkDraft draft=new NetworkDraft(7,initial,catalog);draft.exitId=nodeId;JSONObject candidate=draft.candidate(catalog);catalog.validateAndRun(candidate,current->{vault.save(candidate);});byte[] active=vault.get("network");
      byte[] second=provider("new-fixture");catalog.parsedExitSource(sourceId,generation,1,ExitSubscriptionParser.parse(second),second,System.currentTimeMillis());check("refresh preserves active fixed route bytes",Arrays.equals(active,vault.get("network")));check("credential update preserves stable node ID",nodeId.equals(catalog.exitSource(sourceId).optJSONArray("nodes").optString(0)));boolean denied=false;try{catalog.validateExitSelection(candidate);}catch(Exception expected){denied=true;}check("stale credential revision cannot apply",denied);
      catalog.exitSourceFailed(sourceId,generation,1);check("older failed fetch cannot overwrite successful status",catalog.exitSource(sourceId).optString("lastError").isEmpty());catalog.exitSourceFailed(sourceId,generation,2);check("failed current refresh retains cache",Arrays.equals(second,new NetworkCatalog(this).exitCache(new NetworkCatalog(this).exitSource(sourceId))));
      NetworkCatalog fresh=new NetworkCatalog(this);NetworkDraft updated=new NetworkDraft(7,vault.settings(),fresh);updated.exitId=nodeId;JSONObject updatedCandidate=updated.candidate(fresh);check("deliberate candidate uses new credential revision",!candidate.optString("exitCredentialRevision").equals(updatedCandidate.optString("exitCredentialRevision")));fresh.validateExitSelection(updatedCandidate);
      denied=false;try{fresh.removeExitSource(sourceId);}catch(Exception expected){denied=true;}check("in-use source removal is refused",denied);vault.save(initial);NetworkChanges.save(fixture,"apply",updatedCandidate,NetworkChanges.hash(fixture));denied=false;try{fresh.removeExitSource(sourceId);}catch(Exception expected){denied=true;}check("pending route also protects source removal",denied);NetworkChanges.clear(fixture);
      byte[] onlySecond="socks5://exit-b.example.invalid:1081#renamed\n".getBytes(StandardCharsets.UTF_8);fresh.parsedExitSource(sourceId,generation,2,ExitSubscriptionParser.parse(onlySecond),onlySecond,System.currentTimeMillis());check("removed node is archived and unavailable",!fresh.selectable(fresh.exit(nodeId)));check("existing manual exits remain selectable",fresh.selectable(fresh.exit(NetworkCatalog.exitId(initial))));
      fresh.removeExitSource(sourceId);check("removed source is tombstoned",new NetworkCatalog(this).exitSource(sourceId)==null);denied=false;try{fresh.parsedExitSource(sourceId,generation,3,ExitSubscriptionParser.parse(first),first,System.currentTimeMillis());}catch(Exception expected){denied=true;}check("late response cannot resurrect removed source",denied);
      JSONObject readded=new NetworkCatalog(this).addExitSource("readded",url);check("readd changes source generation",!generation.equals(readded.optString("generation")));denied=false;try{new NetworkCatalog(this).parsedExitSource(sourceId,generation,readded.optLong("revision"),ExitSubscriptionParser.parse(first),first,System.currentTimeMillis());}catch(Exception expected){denied=true;}check("old generation cannot mutate readded source",denied);new NetworkCatalog(this).removeExitSource(sourceId);
      JSONObject entryCandidate=new NetworkDraft(7,initial,new NetworkCatalog(this)).candidate(new NetworkCatalog(this));NetworkCatalog changedEntry=new NetworkCatalog(this);changedEntry.parsed(entry.optString("id"),J.arr("Entry|entry"),new String(entryBytes,StandardCharsets.UTF_8).replace("1080","1082").getBytes(StandardCharsets.UTF_8),System.currentTimeMillis()+100);denied=false;try{changedEntry.validateAndRun(entryCandidate,current->{});}catch(Exception expected){denied=true;}check("same-label changed entry snapshot cannot apply stale bytes",denied);
      byte[] library=fresh.store.get("network-catalog");try{for(String bad:new String[]{"{}","{\"schema\":99,\"subscriptions\":[],\"exits\":[]}","{\"schema\":2.5,\"subscriptions\":[],\"exits\":[]}",new String(library,StandardCharsets.UTF_8)+" trailing"}){fresh.store.put("network-catalog",bad.getBytes(StandardCharsets.UTF_8));byte[] sealed=new android.util.AtomicFile(fresh.store.file("network-catalog")).readFully();NetworkCatalog unreadable=new NetworkCatalog(this);check("corrupt or unsupported catalog is read only",!unreadable.readIssue.isEmpty());denied=false;try{unreadable.save();}catch(Exception expected){denied=true;}check("unreadable catalog save preserves ciphertext",denied&&Arrays.equals(sealed,new android.util.AtomicFile(fresh.store.file("network-catalog")).readFully()));}}finally{fresh.store.put("network-catalog",library);}
    }finally{for(String slot:slots)NetworkUiProvider.restore(vault,slot,before.get(slot));if(!sourceId.isEmpty()){NetworkCatalog clean=new NetworkCatalog(this);if(clean.exitSource(sourceId)!=null&&!clean.sourceInUse(sourceId))clean.removeExitSource(sourceId);}}
  }
}
